const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const state = {token:localStorage.getItem('hoi_token')||'', user:null, page:'dashboard', units:[], personnel:[], reports:[], dues:[], payments:[], audit:[], dashboard:null, posts:[], documents:[], settings:{}, users:[]};
const pageMeta = {
 dashboard:['Tổng quan','BẢNG ĐIỀU KHIỂN','Theo dõi tình hình hoạt động và các nghiệp vụ của Hội.'],
 posts:['Tin tức & sự kiện','NỘI DUNG CÔNG KHAI','Quản lý tin bài, sự kiện hiển thị trên website công khai.'],
 documents:['Văn bản – Biểu mẫu','THƯ VIỆN VĂN BẢN','Quản lý văn bản, quy định và biểu mẫu tải xuống.'],
 units:['Quản lý tổ chức','HỆ THỐNG TỔ CHỨC','Quản lý danh sách đơn vị và cơ cấu trực thuộc.'],
 personnel:['Nhân sự & hội viên','DỮ LIỆU NHÂN SỰ','Thông tin được giới hạn theo vai trò và đơn vị được cấp quyền.'],
 reports:['Báo cáo trực tuyến','QUY TRÌNH BÁO CÁO','Tạo báo cáo, gửi duyệt, phản hồi và xuất dữ liệu.'],
 dues:['Tài chính – Hội phí','QUẢN LÝ HỘI PHÍ','Theo dõi khoản phải thu và trạng thái thanh toán.'],
 payments:['Giao dịch & đối soát','KIỂM SOÁT GIAO DỊCH','Theo dõi tham chiếu, xác minh và xuất bảng đối soát.'],
 users:['Tài khoản & quyền','QUẢN LÝ TÀI KHOẢN','Tạo, sửa, khóa, mở khóa và cấp quyền tài khoản.'],
 settings:['Cấu hình website','THÔNG TIN HIỂN THỊ CÔNG KHAI','Cập nhật thông tin Hội hiển thị trên website công khai.'],
 audit:['Nhật ký hệ thống','AN TOÀN & KIỂM SOÁT','Theo dõi các thao tác quan trọng trong hệ thống.']
};
const POST_CATS={'chinh-sach':'Chính sách y tế','hoat-dong':'Hoạt động Hội','hoi-nghi':'Hội nghị – Hội thảo','thien-nguyen':'Thiện nguyện','the-thao':'Thể thao','van-nghe':'Văn nghệ','dao-tao':'Đào tạo – Bồi dưỡng','thong-bao':'Thông báo','don-vi':'Hoạt động đơn vị'};
const DOC_CATS={'gioi-thieu':'Giới thiệu Hội','to-chuc':'Quản trị tổ chức','nhan-su':'Quản trị nhân sự','tai-chinh':'Tài chính – Hội phí','bao-cao':'Chế độ báo cáo','khac':'Tài liệu khác'};
const DOC_TYPES=['Điều lệ','Quyết định','Quy chế','Hướng dẫn','Biểu mẫu','Báo cáo','Khác'];
const UNIT_TYPES={'trung_uong':'Trung ương Hội','ban_chuyen_mon':'Ban chuyên môn','lien_chi_hoi':'Liên chi hội','chi_hoi':'Chi hội','vien_trung_tam':'Viện / Trung tâm','vp_dai_dien':'Văn phòng đại diện','doanh_nghiep':'Doanh nghiệp hội viên'};
const PEOPLE_GROUPS={'bch':'Ban Chấp hành Trung ương','bttv':'Ban Thường vụ','lanh_dao_don_vi':'Lãnh đạo đơn vị','can_bo':'Cán bộ, hội viên'};
const roleNames={admin:'Quản trị viên',reviewer:'Người duyệt báo cáo',unit_lead:'Trưởng đơn vị',viewer:'Chỉ xem',finance:'Phụ trách tài chính'};
const money = n => new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(Number(n||0));
const dateText = v => v ? new Date(String(v).replace(/-\d\d:\d\d:\d\d.*$/,'').replace(' ','T')).toLocaleDateString('vi-VN') : '—';
const esc = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials = s => String(s||'?').trim().split(/\s+/).slice(-2).map(x=>x[0]).join('').toUpperCase();
async function api(path, options={}) {
 const headers={'Content-Type':'application/json',...(options.headers||{})}; if(state.token) headers.Authorization='Bearer '+state.token;
 const res=await fetch('/api'+path,{...options,headers});
 if(res.status===401 && path!='/auth/login'){logout(false);throw new Error('Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.');}
 const type=res.headers.get('content-type')||''; const data=type.includes('application/json')?await res.json():await res.text();
 if(!res.ok) throw new Error(data.error||'Có lỗi xảy ra, vui lòng thử lại'); return data;
}
function toast(msg,error=false){const el=$('#toast');el.textContent=msg;el.className='toast show'+(error?' error':'');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.className='toast',3400)}
function setLoggedIn(user){state.user=user;$('#loginScreen').classList.add('hidden');$('#appShell').classList.remove('hidden');$('#profileName').textContent=user.full_name;$('#profileRole').textContent=roleNames[user.role]||user.role;$('#avatar').textContent=initials(user.full_name);$('#headerDate').textContent=new Intl.DateTimeFormat('vi-VN',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).format(new Date());$$('[data-role="admin"]').forEach(el=>el.classList.toggle('hidden',user.role!=='admin'));renderPage('dashboard')}
function logout(show=true){state.token='';state.user=null;localStorage.removeItem('hoi_token');$('#appShell').classList.add('hidden');$('#loginScreen').classList.remove('hidden');$('#profileMenu').classList.add('hidden');if(show)toast('Bạn đã đăng xuất thành công')}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginError').textContent='';const btn=e.submitter;btn.disabled=true;btn.textContent='Đang xác thực…';try{const d=await api('/auth/login',{method:'POST',body:JSON.stringify({username:$('#username').value,password:$('#password').value})});state.token=d.token;localStorage.setItem('hoi_token',d.token);setLoggedIn(d.user);toast('Đăng nhập thành công. Xin chào '+d.user.full_name)}catch(err){$('#loginError').textContent=err.message}finally{btn.disabled=false;btn.innerHTML='Đăng nhập <span>→</span>'}});
$('#togglePassword').onclick=()=>{const i=$('#password');i.type=i.type==='password'?'text':'password'};
$('#logoutBtn').onclick=()=>logout();$('#profileBtn').onclick=()=>$('#profileMenu').classList.toggle('hidden');document.addEventListener('click',e=>{if(!e.target.closest('.profile-wrap'))$('#profileMenu').classList.add('hidden')});
$('#menuToggle').onclick=()=>{ $('#sidebar').classList.add('open');$('#sidebarScrim').classList.add('show')};$('#sidebarClose').onclick=$('#sidebarScrim').onclick=()=>{$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show')};
$('#sideNav').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)renderPage(b.dataset.page)});
$('#notificationBtn').onclick=()=>toast('Thông báo: các nghiệp vụ sẽ hiển thị tại đây khi được cập nhật.');
$('#changePasswordBtn').onclick=()=>openModal('Đổi mật khẩu','Bảo vệ tài khoản của bạn',`<div class="form-field"><label>Mật khẩu hiện tại</label><input type="password" id="oldPass" required></div><div class="form-field"><label>Mật khẩu mới (ít nhất 10 ký tự)</label><input type="password" id="newPass" minlength="10" required></div><div class="form-field"><label>Nhập lại mật khẩu mới</label><input type="password" id="confirmPass" minlength="10" required></div>`,async()=>{const old=$('#oldPass').value,n=$('#newPass').value,c=$('#confirmPass').value;if(n!==c)throw Error('Mật khẩu nhập lại chưa khớp');await api('/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword:old,newPassword:n})});toast('Đổi mật khẩu thành công')});
function openModal(title,subtitle,body,onSave,saveLabel='Lưu thông tin'){const root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><section class="modal"><header class="modal-head"><div><span class="eyebrow">THAO TÁC HỆ THỐNG</span><h2>${esc(title)}</h2><p>${esc(subtitle||'Vui lòng kiểm tra thông tin trước khi lưu.')}</p></div><button class="modal-close" id="modalClose">×</button></header><form id="modalForm"><div class="modal-body">${body}</div><footer class="modal-foot"><button type="button" class="btn btn-outline" id="modalCancel">Hủy</button><button class="btn btn-primary" type="submit">${esc(saveLabel)} →</button></footer></form></section></div>`;const close=()=>root.innerHTML='';$('#modalClose').onclick=$('#modalCancel').onclick=close;root.querySelector('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))close()});$('#modalForm').onsubmit=async e=>{e.preventDefault();const btn=e.submitter;btn.disabled=true;btn.textContent='Đang lưu…';try{await onSave();close();await renderPage(state.page)}catch(err){toast(err.message,true)}finally{if(btn.isConnected){btn.disabled=false;btn.textContent=saveLabel+' →'}}}}
function pageHeader(page){const m=pageMeta[page];$('#crumbTitle').textContent=m[0];$('#pageHeader').querySelector('.eyebrow').textContent=m[1];$('#pageHeader').querySelector('h1').textContent=m[0];$('#pageHeader').querySelector('p').textContent=m[2];$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#sidebar').classList.remove('open');$('#sidebarScrim').classList.remove('show')}
async function renderPage(page){if(!pageMeta[page])page='dashboard';state.page=page;pageHeader(page);const c=$('#pageContent');c.innerHTML='<div class="card empty-state">Đang tải dữ liệu…</div>';try{if(page==='dashboard')c.innerHTML=await dashboardHtml();if(page==='posts')c.innerHTML=await postsHtml();if(page==='documents')c.innerHTML=await documentsHtml();if(page==='users')c.innerHTML=await usersHtml();if(page==='settings')c.innerHTML=await settingsHtml();if(page==='units')c.innerHTML=await unitsHtml();if(page==='personnel')c.innerHTML=await personnelHtml();if(page==='reports')c.innerHTML=await reportsHtml();if(page==='dues')c.innerHTML=await duesHtml();if(page==='payments')c.innerHTML=await paymentsHtml();if(page==='audit')c.innerHTML=await auditHtml();bindPageEvents(page)}catch(err){c.innerHTML=`<div class="card empty-state">${esc(err.message)}<br><br><button class="btn btn-soft" onclick="renderPage('${page}')">Thử tải lại</button></div>`}}
function statCard(label,value,foot,icon,color){return `<article class="stat-card"><div class="stat-top"><span class="stat-label">${label}</span><span class="stat-icon ${color}">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`}
async function dashboardHtml(){const d=await api('/dashboard');state.dashboard=d;$('#reportNavCount').textContent=d.stats.pending;const unitLabel=state.user.role==='unit_lead'?'Đơn vị của bạn':'Toàn hệ thống';return `<div class="stats-grid">${statCard('Đơn vị trực thuộc',d.stats.units,'<span class="up">●</span> '+unitLabel,'⌂','blue')}${statCard('Nhân sự & hội viên',d.stats.people,'Dữ liệu theo phạm vi được cấp quyền','♙','green')}${statCard('Báo cáo chờ duyệt',d.stats.pending,'Theo dõi tiến độ xử lý','▤','orange')}${statCard('Hội phí chưa thu',money(d.stats.unpaid),'Tổng khoản phải thu còn lại','₫','purple')}</div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h3>Hoạt động nghiệp vụ</h3><p>Tổng quan nhanh các đầu việc gần đây</p></div><div class="chart-legend"><span><i style="background:#247bf1"></i>Báo cáo</span><span><i style="background:#16b88a"></i>Hội phí</span></div></div><div class="chart-area"><canvas id="activityChart" aria-label="Biểu đồ minh họa hoạt động"></canvas></div></section><section class="card"><div class="card-head"><div><h3>Báo cáo gần đây</h3><p>Cập nhật theo thời gian</p></div><button class="small-link" data-goto="reports">Xem tất cả →</button></div><div class="activity-list">${d.reports.length?d.reports.slice(0,5).map(r=>`<div class="activity-row"><span class="activity-symbol">▤</span><div class="activity-main"><b>${esc(r.title)}</b><small>${esc(r.unit_name)} · ${esc(r.created_by_name)}</small></div><div class="activity-time">${statusBadge(r.status)}</div></div>`).join(''):'<div class="empty-state">Chưa có báo cáo.</div>'}</div></section></div><div class="section-title" style="margin:22px 0 12px">Truy cập nhanh</div><div class="quick-grid"><button class="quick-action" data-goto="units"><span class="qicon">⌂</span><span><b>Quản lý tổ chức</b><small>Xem các đơn vị trực thuộc</small></span></button><button class="quick-action" data-goto="personnel"><span class="qicon">♙</span><span><b>Nhân sự & hội viên</b><small>Cập nhật thông tin theo quyền</small></span></button><button class="quick-action" data-goto="reports"><span class="qicon">▤</span><span><b>Tạo báo cáo</b><small>Gửi và theo dõi phê duyệt</small></span></button><button class="quick-action" data-goto="dues"><span class="qicon">₫</span><span><b>Quản lý hội phí</b><small>Theo dõi khoản phải thu</small></span></button></div><div class="notice"><span>ⓘ</span><div><strong>Lưu ý về bản thử nghiệm</strong> Dữ liệu đang được lưu tại cơ sở dữ liệu của máy chủ đang chạy. Thanh toán chưa kết nối ngân hàng/cổng thanh toán thật; giao dịch demo không trừ tiền.</div></div>`}
function statusBadge(s){const cls=({'Đã duyệt':'green','Đã xác minh':'green','Đã thanh toán':'green','Đã xuất bản':'green','Đang hoạt động':'green','Chờ duyệt':'blue','Chờ xác minh':'orange','Yêu cầu sửa':'orange','Chưa thanh toán':'orange','Bản nháp':'gray','Không khớp':'red','Thất bại':'red','Tạm ngừng':'gray'})[s]||'gray';return `<span class="badge ${cls}">${esc(s)}</span>`}
async function unitsHtml(){state.units=await api('/units');const canEdit=state.user.role==='admin';const typeOpts=[...new Set(state.units.map(u=>u.unit_type))];return `<div class="toolbar"><div class="search-box">⌕ <input id="tableSearch" placeholder="Tìm theo tên hoặc mã đơn vị…"></div><select id="unitFilter" class="filter-select"><option value="">Tất cả loại hình</option>${typeOpts.map(t=>`<option value="${t}">${esc(UNIT_TYPES[t]||t)}</option>`).join('')}</select>${canEdit?'<button class="btn btn-primary" id="addUnit">＋ Thêm đơn vị</button>':''}</div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>MÃ</th><th>ĐƠN VỊ</th><th>LOẠI HÌNH</th><th>NGƯỜI ĐỨNG ĐẦU</th><th>NHÂN SỰ</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody id="dataRows">${state.units.map(u=>`<tr data-search="${esc((u.code+' '+u.name).toLowerCase())}" data-type="${esc(u.unit_type)}"><td><b>${esc(u.code)}</b></td><td><div class="person-cell"><span class="mini-avatar">⌂</span><span><b>${esc(u.name)}</b><small>Đơn vị trực thuộc Hội</small></span></div></td><td>${esc(UNIT_TYPES[u.unit_type]||u.unit_type)}</td><td>${esc(u.head_name||'—')}</td><td>${u.people_count} người</td><td>${statusBadge(u.status==='inactive'?'Tạm ngừng':'Đang hoạt động')}</td><td><div class="row-actions"><button class="action-btn" title="Xem trên website" data-unit-public="${esc(u.slug||u.id)}">↗</button>${canEdit?`<button class="action-btn" title="Chỉnh sửa" data-edit-unit="${u.id}">✎</button><button class="action-btn" title="Xóa" data-delete-unit="${u.id}">×</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${state.units.length} đơn vị trong hệ thống</span><span>Dữ liệu máy chủ · cập nhật trực tiếp</span></div></section>`}
async function personnelHtml(){state.personnel=await api('/personnel');if(!state.units.length)state.units=await api('/units');const canAdd=['admin','unit_lead'].includes(state.user.role);return `<div class="toolbar"><div class="search-box">⌕ <input id="tableSearch" placeholder="Tìm theo họ tên, chức vụ, email…"></div><select class="filter-select" id="personUnitFilter"><option value="">Tất cả đơn vị được phép xem</option>${state.units.filter(u=>state.user.role!=='unit_lead'||u.id===state.user.unit_id).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select>${canAdd?'<button class="btn btn-primary" id="addPerson">＋ Thêm nhân sự</button>':''}</div><div class="notice"><span>🔐</span><div><strong>Phạm vi dữ liệu được bảo vệ</strong> ${state.user.role==='unit_lead'?'Bạn chỉ xem và cập nhật nhân sự thuộc đơn vị của mình.':'Thông tin hiển thị theo quyền của tài khoản đang đăng nhập.'} Chỉ nhập dữ liệu thật khi hệ thống đã được triển khai bảo mật chính thức.</div></div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>NHÂN SỰ</th><th>ĐƠN VỊ</th><th>CHỨC VỤ</th><th>LIÊN HỆ</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody id="dataRows">${state.personnel.map(p=>`<tr data-search="${esc((p.full_name+' '+p.title+' '+p.position+' '+p.email+' '+p.unit_name).toLowerCase())}" data-unit="${p.unit_id}"><td><div class="person-cell"><span class="mini-avatar">${initials(p.full_name)}</span><span><b>${esc(p.full_name)}</b><small>Mã hồ sơ #${p.id.toString().padStart(4,'0')}${p.is_public?' · Công khai':''}</small></span></div></td><td>${esc(p.unit_name)}</td><td>${esc(p.position||p.title||'—')}${p.group_role?`<small style="display:block;color:#8b99ac">${esc(PEOPLE_GROUPS[p.group_role]||p.group_role)}</small>`:''}</td><td><span>${esc(p.email||'—')}</span><br><small style="color:#8b99ac">${esc(p.phone||'')}</small></td><td>${statusBadge(p.status)}</td><td><div class="row-actions">${canAdd?`<button class="action-btn" title="Chỉnh sửa" data-edit-person="${p.id}">✎</button>`:''}${state.user.role==='admin'?`<button class="action-btn" title="Xóa" data-delete-person="${p.id}">×</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${state.personnel.length} hồ sơ trong phạm vi được phép</span><span>Thông tin liên hệ được giới hạn theo vai trò</span></div></section>`}
async function reportsHtml(){state.reports=await api('/reports');$('#reportNavCount').textContent=state.reports.filter(r=>r.status==='Chờ duyệt').length;const canCreate=['admin','unit_lead'].includes(state.user.role);const canReview=['admin','reviewer'].includes(state.user.role);return `<div class="workflow"><div class="workflow-step"><span class="step-number">01</span><span><b>Tạo báo cáo</b><small>Nhập kỳ báo cáo và nội dung</small></span></div><div class="workflow-step"><span class="step-number">02</span><span><b>Gửi & phê duyệt</b><small>Người có quyền xem xét</small></span></div><div class="workflow-step"><span class="step-number">03</span><span><b>Xuất báo cáo</b><small>Tải dữ liệu CSV để xử lý</small></span></div></div><div class="toolbar"><div class="search-box">⌕ <input id="tableSearch" placeholder="Tìm báo cáo hoặc kỳ báo cáo…"></div><select id="reportStatusFilter" class="filter-select"><option value="">Tất cả trạng thái</option><option>Nháp</option><option>Chờ duyệt</option><option>Đã duyệt</option><option>Yêu cầu sửa</option></select><button class="btn btn-outline" id="exportReports">↓ Xuất CSV</button>${canCreate?'<button class="btn btn-primary" id="addReport">＋ Tạo báo cáo</button>':''}</div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>BÁO CÁO</th><th>ĐƠN VỊ</th><th>KỲ BÁO CÁO</th><th>NGƯỜI TẠO</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody id="dataRows">${state.reports.map(r=>`<tr data-search="${esc((r.title+' '+r.period+' '+r.unit_name).toLowerCase())}" data-status="${esc(r.status)}"><td><div class="person-cell"><span class="mini-avatar">▤</span><span><b>${esc(r.title)}</b><small>Mã báo cáo #${r.id} · ${dateText(r.created_at)}</small></span></div></td><td>${esc(r.unit_name)}</td><td>${esc(r.period)}</td><td>${esc(r.created_by_name)}</td><td>${statusBadge(r.status)}</td><td><div class="row-actions"><button class="action-btn" title="Xem nội dung" data-view-report="${r.id}">↗</button>${canCreate&&['Nháp','Yêu cầu sửa'].includes(r.status)?`<button class="action-btn" title="Gửi duyệt" data-submit-report="${r.id}">➤</button>`:''}${canReview&&r.status==='Chờ duyệt'?`<button class="action-btn" title="Duyệt báo cáo" data-review-report="${r.id}">✓</button>`:''}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${state.reports.length} báo cáo</span><span>${state.reports.filter(r=>r.status==='Chờ duyệt').length} báo cáo đang chờ duyệt</span></div></section>`}
async function duesHtml(){state.dues=await api('/dues');const unpaid=state.dues.filter(d=>d.status==='Chưa thanh toán').reduce((a,d)=>a+d.amount,0);const paid=state.dues.filter(d=>d.status==='Đã thanh toán').reduce((a,d)=>a+d.amount,0);const canPay=['admin','unit_lead','finance'].includes(state.user.role);return `<div class="finance-summary"><div class="card finance-card"><small>Tổng khoản phải thu còn lại</small><strong>${money(unpaid)}</strong><p>Khoản hội phí chưa xác minh hoàn tất</p></div><div class="card finance-card"><small>Đã ghi nhận thanh toán</small><strong>${money(paid)}</strong><p>Chỉ tính khoản đã được xác minh</p></div><div class="card finance-card"><small>Số khoản hội phí</small><strong>${state.dues.length}</strong><p>Trong phạm vi dữ liệu được cấp</p></div></div><div class="notice"><span>ⓘ</span><div><strong>Thanh toán thật chưa được kích hoạt</strong> Chức năng hiện ghi nhận yêu cầu giao dịch thử nghiệm và xác minh thủ công. Chưa kết nối ngân hàng, ví điện tử hoặc cổng thanh toán; không phát sinh thu tiền thật.</div></div><div class="toolbar"><div class="search-box">⌕ <input id="tableSearch" placeholder="Tìm đơn vị hoặc kỳ hội phí…"></div><select id="duesFilter" class="filter-select"><option value="">Tất cả trạng thái</option><option>Chưa thanh toán</option><option>Đã thanh toán</option></select></div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>ĐƠN VỊ</th><th>KỲ HỘI PHÍ</th><th>SỐ TIỀN</th><th>TRẠNG THÁI</th><th>GIAO DỊCH GẦN NHẤT</th><th>THAO TÁC</th></tr></thead><tbody id="dataRows">${state.dues.map(d=>`<tr data-search="${esc((d.unit_name+' '+d.period).toLowerCase())}" data-status="${esc(d.status)}"><td><div class="person-cell"><span class="mini-avatar">₫</span><span><b>${esc(d.unit_name)}</b><small>Khoản phải thu #${d.id}</small></span></div></td><td>${esc(d.period)}</td><td><b>${money(d.amount)}</b></td><td>${statusBadge(d.status)}</td><td>${d.transaction_ref?`${esc(d.transaction_ref)}<br>${statusBadge(d.payment_status)}`:'<span style="color:#9aa7b7">Chưa có giao dịch</span>'}</td><td>${canPay&&d.status!=='Đã thanh toán'?`<button class="btn btn-soft" style="padding:8px 10px;font-size:9px" data-pay-dues="${d.id}">Tạo giao dịch</button>`:'—'}</td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${state.dues.length} khoản hội phí</span><span>VND · Bản demo</span></div></section>`}
async function paymentsHtml(){state.payments=await api('/dues');const list=state.payments.filter(d=>d.transaction_ref);const canVerify=['admin','finance'].includes(state.user.role);return `<div class="notice"><span>🛡</span><div><strong>Quy trình đối soát</strong> Mỗi yêu cầu có mã tham chiếu riêng. Chỉ đánh dấu “Đã xác minh” sau khi đối chiếu với sao kê hoặc webhook đã xác thực của nhà cung cấp thanh toán.</div></div><div class="toolbar"><div class="search-box">⌕ <input id="tableSearch" placeholder="Tìm mã giao dịch hoặc đơn vị…"></div><select id="paymentFilter" class="filter-select"><option value="">Tất cả trạng thái</option><option>Chờ xác minh</option><option>Đã xác minh</option><option>Không khớp</option><option>Thất bại</option></select>${canVerify?'<button class="btn btn-outline" id="exportPayments">↓ Xuất đối soát CSV</button>':''}</div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>MÃ THAM CHIẾU</th><th>ĐƠN VỊ / KỲ</th><th>SỐ TIỀN</th><th>PHƯƠNG THỨC</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody id="dataRows">${list.map(d=>`<tr data-search="${esc(((d.transaction_ref||'')+' '+d.unit_name+' '+d.period+' '+(d.provider_ref||'')).toLowerCase())}" data-status="${esc(d.payment_status||'')}"><td><b>${esc(d.transaction_ref)}</b><small style="display:block;color:#8b99ac;margin-top:5px">${dateText(d.payment_created)}</small></td><td>${esc(d.unit_name)}<small style="display:block;color:#8b99ac;margin-top:5px">${esc(d.period)}</small></td><td><b>${money(d.amount)}</b></td><td>${esc(d.method||'—')}</td><td>${statusBadge(d.payment_status||'Chờ xác minh')}${d.provider_ref?`<small style="display:block;color:#8b99ac;margin-top:5px">Mã ngân hàng: ${esc(d.provider_ref)}</small>`:''}</td><td>${canVerify&&d.payment_status==='Chờ xác minh'?`<button class="action-btn" title="Xác minh" data-verify-payment="${d.id}">✓</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">Chưa có giao dịch. Tạo yêu cầu từ mục Tài chính – Hội phí.</div></td></tr>'}</tbody></table></div><div class="table-footer"><span>${list.length} giao dịch</span><span>Giao dịch demo không đại diện cho khoản tiền đã nhận</span></div></section>`}
async function auditHtml(){state.audit=await api('/audit');return `<div class="notice"><span>◷</span><div><strong>Nhật ký kiểm toán</strong> Ghi nhận đăng nhập và các thay đổi quan trọng. Chỉ quản trị viên được xem mục này.</div></div><section class="card"><div class="card-head"><div><h3>Lịch sử thao tác gần đây</h3><p>100 bản ghi mới nhất</p></div><button class="btn btn-outline" id="refreshAudit">↻ Làm mới</button></div><div class="panel-pad">${state.audit.map(a=>`<div class="audit-line"><span>${dateText(a.created_at)}<br><small>${esc(a.created_at)}</small></span><span><b>${esc(a.action)}</b> · ${esc(a.entity)} #${esc(a.entity_id)}<br><small>${esc(a.detail||'Không có mô tả bổ sung')}</small></span><span>${esc(a.full_name||'Hệ thống')}<br><small>@${esc(a.username||'system')}</small></span></div>`).join('')||'<div class="empty-state">Chưa có nhật ký.</div>'}</div></section>`}
function bindSearch(){const search=$('#tableSearch');const filter=$('#unitFilter')||$('#personUnitFilter')||$('#postTypeFilter')||$('#docTypeFilter')||$('#userRoleFilter');const status=$('#reportStatusFilter')||$('#duesFilter')||$('#paymentFilter')||$('#postStatusFilter');const filterKey=filter?.id==='unitFilter'?'unitType':filter?.id==='postTypeFilter'?'postType':filter?.id==='docTypeFilter'?'docType':filter?.id==='userRoleFilter'?'role':'unit';const apply=()=>{$$('#dataRows tr').forEach(tr=>{const okSearch=!search||tr.dataset.search?.includes(search.value.toLowerCase());const okFilter=!filter||!filter.value||tr.dataset[filterKey]===filter.value;const okStatus=!status||!status.value||tr.dataset.status===status.value;tr.style.display=okSearch&&okFilter&&okStatus?'':'none'})};search?.addEventListener('input',apply);filter?.addEventListener('change',apply);status?.addEventListener('change',apply)}
function bindPageEvents(page){bindSearch();$$('[data-goto]').forEach(b=>b.onclick=()=>renderPage(b.dataset.goto));if(page==='dashboard')drawChart();if(page==='posts'){$('#addPost')?.addEventListener('click',()=>postModal());$$('[data-edit-post]').forEach(b=>b.onclick=()=>postModal(state.posts.find(x=>x.id===Number(b.dataset.editPost))));$$('[data-delete-post]').forEach(b=>b.onclick=()=>deleteContent('/posts',Number(b.dataset.deletePost),'bài viết'))}if(page==='documents'){$('#addDoc')?.addEventListener('click',()=>docModal());$$('[data-edit-doc]').forEach(b=>b.onclick=()=>docModal(state.documents.find(x=>x.id===Number(b.dataset.editDoc))));$$('[data-delete-doc]').forEach(b=>b.onclick=()=>deleteContent('/documents',Number(b.dataset.deleteDoc),'văn bản'))}if(page==='users'){$('#addUser')?.addEventListener('click',()=>userModal());$$('[data-edit-user]').forEach(b=>b.onclick=()=>userModal(state.users.find(x=>x.id===Number(b.dataset.editUser))));$$('[data-toggle-user]').forEach(b=>b.onclick=()=>toggleUser(Number(b.dataset.toggleUser)));$$('[data-reset-pass]').forEach(b=>b.onclick=()=>resetPassword(Number(b.dataset.resetPass)))}if(page==='settings')$('#saveSettings')?.addEventListener('click',saveSettings);if(page==='units'){$('#addUnit')?.addEventListener('click',()=>addUnitModal());$$('[data-edit-unit]').forEach(b=>b.onclick=()=>addUnitModal(state.units.find(x=>x.id===Number(b.dataset.editUnit))));$$('[data-delete-unit]').forEach(b=>b.onclick=()=>deleteUnit(Number(b.dataset.deleteUnit)));$$('[data-unit-public]').forEach(b=>b.onclick=()=>window.open('/to-chuc/'+b.dataset.unitPublic,'_blank'))}if(page==='personnel'){$('#addPerson')?.addEventListener('click',()=>personModal());$$('[data-edit-person]').forEach(b=>b.onclick=()=>personModal(state.personnel.find(p=>p.id===Number(b.dataset.editPerson))));$$('[data-delete-person]').forEach(b=>b.onclick=()=>deletePerson(Number(b.dataset.deletePerson)))}if(page==='reports'){$('#addReport')?.addEventListener('click',reportModal);$('#exportReports')?.addEventListener('click',()=>downloadFile('/reports/export.csv'));$$('[data-view-report]').forEach(b=>b.onclick=()=>viewReport(Number(b.dataset.viewReport)));$$('[data-submit-report]').forEach(b=>b.onclick=()=>submitReport(Number(b.dataset.submitReport)));$$('[data-review-report]').forEach(b=>b.onclick=()=>reviewReport(Number(b.dataset.reviewReport)))}if(page==='dues')$$('[data-pay-dues]').forEach(b=>b.onclick=()=>paymentModal(Number(b.dataset.payDues)));if(page==='payments'){$('#exportPayments')?.addEventListener('click',()=>downloadFile('/payments/export.csv'));$$('[data-verify-payment]').forEach(b=>b.onclick=()=>verifyPayment(Number(b.dataset.verifyPayment)))}if(page==='audit')$('#refreshAudit')?.addEventListener('click',()=>renderPage('audit'))}
function drawChart(){const canvas=$('#activityChart');if(!canvas)return;const ctx=canvas.getContext('2d');const rect=canvas.getBoundingClientRect();const dpr=window.devicePixelRatio||1;canvas.width=rect.width*dpr;canvas.height=rect.height*dpr;ctx.scale(dpr,dpr);const w=rect.width,h=rect.height;const pad={l:28,r:12,t:12,b:25};ctx.clearRect(0,0,w,h);ctx.font='9px "Be Vietnam Pro", sans-serif';ctx.fillStyle='#8b9bb0';for(let i=0;i<5;i++){const y=pad.t+(h-pad.t-pad.b)*i/4;ctx.strokeStyle='#edf1f7';ctx.beginPath();ctx.moveTo(pad.l,y);ctx.lineTo(w-pad.r,y);ctx.stroke();ctx.fillText(String(40-i*10),3,y+3)}const labels=['T1','T2','T3','T4','T5','T6','T7','T8','T9','T10','T11','T12'];labels.forEach((x,i)=>ctx.fillText(x,pad.l+i*(w-pad.l-pad.r)/11-5,h-6));const lines=[{c:'#247bf1',v:[8,12,15,13,20,24,22,27,25,33,30,36]},{c:'#16b88a',v:[5,7,9,8,11,10,15,13,17,15,20,22]}];lines.forEach(line=>{ctx.strokeStyle=line.c;ctx.lineWidth=2.2;ctx.lineJoin='round';ctx.beginPath();line.v.forEach((v,i)=>{const x=pad.l+i*(w-pad.l-pad.r)/11;const y=h-pad.b-v/40*(h-pad.t-pad.b);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke();line.v.forEach((v,i)=>{const x=pad.l+i*(w-pad.l-pad.r)/11;const y=h-pad.b-v/40*(h-pad.t-pad.b);ctx.fillStyle=line.c;ctx.beginPath();ctx.arc(x,y,2.5,0,Math.PI*2);ctx.fill()})})}
window.addEventListener('resize',()=>{if(state.page==='dashboard')drawChart()});
function addUnitModal(u=null){const parentOpts=u?state.units.filter(x=>x.id!==u.id).map(x=>`<option value="${x.id}" ${u.parent_id===x.id?'selected':''}>${esc(x.name)}</option>`).join(''):state.units.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');const typeOpts=Object.entries(UNIT_TYPES).map(([k,v])=>`<option value="${k}" ${u&&u.unit_type===k?'selected':''}>${esc(v)}</option>`).join('');openModal(u?'Cập nhật đơn vị':'Thêm đơn vị mới',u?'Thông tin tổ chức, địa chỉ và người đứng đầu được hiển thị trên website công khai.':'Đơn vị mới sẽ được lưu vào cơ sở dữ liệu dùng chung.',`<div class="form-grid"><div class="form-field"><label>Tên đơn vị *</label><input id="unitName" required value="${esc(u?.name||'')}" placeholder="Ví dụ: Chi hội Quảng Ninh"></div><div class="form-field"><label>Mã đơn vị *</label><input id="unitCode" required value="${esc(u?.code||'')}" placeholder="Ví dụ: QN"></div><div class="form-field"><label>Loại hình tổ chức</label><select id="unitType">${typeOpts}</select></div><div class="form-field"><label>Đơn vị cấp trên</label><select id="unitParent"><option value="">— Không có —</option>${parentOpts}</select></div><div class="form-field"><label>Người đứng đầu</label><input id="unitHead" value="${esc(u?.head_name||'')}" placeholder="Họ tên lãnh đạo đơn vị"></div><div class="form-field"><label>Ngày thành lập</label><input id="unitFounded" type="date" value="${esc(u?.founded_at||'')}"></div><div class="form-field"><label>Địa chỉ</label><input id="unitAddress" value="${esc(u?.address||'')}"></div><div class="form-field"><label>Điện thoại</label><input id="unitPhone" value="${esc(u?.phone||'')}"></div><div class="form-field"><label>Email</label><input id="unitEmail" value="${esc(u?.email||'')}"></div><div class="form-field"><label>Trạng thái</label><select id="unitStatus"><option value="active" ${u?.status==='active'?'selected':''}>Đang hoạt động</option><option value="inactive" ${u?.status==='inactive'?'selected':''}>Tạm ngừng</option></select></div><div class="form-field full"><label>Mô tả giới thiệu</label><textarea id="unitDesc">${esc(u?.description||'')}</textarea></div><div class="form-field full"><label class="check"><input type="checkbox" id="unitPublic" ${u&&u.is_public===0?'':'checked'}> <b>Hiển thị công khai trên website</b></label></div></div>`,async()=>{const data={name:$('#unitName').value,code:$('#unitCode').value,unit_type:$('#unitType').value,parent_id:$('#unitParent').value||null,head_name:$('#unitHead').value,founded_at:$('#unitFounded').value||null,address:$('#unitAddress').value,phone:$('#unitPhone').value,email:$('#unitEmail').value,description:$('#unitDesc').value,status:$('#unitStatus').value,is_public:$('#unitPublic').checked};await api(u?'/units/'+u.id:'/units',{method:u?'PUT':'POST',body:JSON.stringify(data)});toast(u?'Đã cập nhật đơn vị':'Đã thêm đơn vị')},u?'Cập nhật':'Thêm đơn vị')}
async function deleteUnit(id){const u=state.units.find(x=>x.id===id);if(!confirm(`Xóa đơn vị “${u.name}”? Chỉ xóa được khi đơn vị không còn đơn vị trực thuộc hoặc nhân sự.`))return;try{await api('/units/'+id,{method:'DELETE'});toast('Đã xóa đơn vị');renderPage('units')}catch(e){toast(e.message,true)}}
function personModal(p=null){const options=state.units.filter(u=>state.user.role!=='unit_lead'||u.id===state.user.unit_id).map(u=>`<option value="${u.id}" ${p&&p.unit_id===u.id?'selected':''}>${esc(u.name)}</option>`).join('');const groupOpts=Object.entries(PEOPLE_GROUPS).map(([k,v])=>`<option value="${k}" ${p&&p.group_role===k?'selected':''}>${esc(v)}</option>`).join('');openModal(p?'Cập nhật hồ sơ nhân sự':'Thêm nhân sự mới',p?'Chỉnh sửa thông tin hồ sơ và trạng thái công khai.':'Chỉ nhập thông tin cần thiết cho nghiệp vụ.',`<div class="form-grid"><div class="form-field full"><label>Họ và tên *</label><input id="pName" required value="${esc(p?.full_name||'')}" placeholder="Nhập họ và tên"></div><div class="form-field"><label>Chức vụ trong Hội</label><input id="pPosition" value="${esc(p?.position||'')}" placeholder="Ví dụ: Chủ tịch Chi hội"></div><div class="form-field"><label>Chức danh (tiêu đề)</label><input id="pTitle" value="${esc(p?.title||'')}" placeholder="Tiêu đề ngắn gọn"></div><div class="form-field"><label>Nhóm công khai</label><select id="pGroup">${groupOpts}</select></div><div class="form-field"><label>Đơn vị *</label><select id="pUnit" required>${options}</select></div><div class="form-field"><label>Nhiệm kỳ</label><input id="pTerm" value="${esc(p?.term||'')}" placeholder="Ví dụ: 2025–2030"></div><div class="form-field"><label>Email công việc</label><input id="pEmail" type="email" value="${esc(p?.email||'')}" placeholder="email@donvi.vn"></div><div class="form-field"><label>Số điện thoại</label><input id="pPhone" value="${esc(p?.phone||'')}" placeholder="Số liên hệ"></div><div class="form-field"><label>Trạng thái</label><select id="pStatus"><option ${p&&p.status==='Đang hoạt động'?'selected':''}>Đang hoạt động</option><option ${p&&p.status==='Nghỉ công tác'?'selected':''}>Nghỉ công tác</option><option ${p&&p.status==='Chấm dứt tư cách'?'selected':''}>Chấm dứt tư cách</option></select></div><div class="form-field"><label>Thứ tự hiển thị</label><input id="pSort" type="number" value="${p?.sort_order||0}"></div><div class="form-field full"><label>Tiểu sử / giới thiệu (hiển thị công khai)</label><textarea id="pBio">${esc(p?.bio||'')}</textarea></div><div class="form-field full"><label class="check"><input type="checkbox" id="pPublic" ${p?.is_public?'checked':''}> <b>Cho phép hiển thị công khai hồ sơ này trên website</b></label></div></div>`,async()=>{const data={full_name:$('#pName').value,position:$('#pPosition').value,title:$('#pTitle').value,group_role:$('#pGroup').value,unit_id:Number($('#pUnit').value),term:$('#pTerm').value,email:$('#pEmail').value,phone:$('#pPhone').value,status:$('#pStatus').value,sort_order:Number($('#pSort').value||0),bio:$('#pBio').value,is_public:$('#pPublic').checked};await api(p?'/personnel/'+p.id:'/personnel',{method:p?'PUT':'POST',body:JSON.stringify(data)});toast(p?'Đã cập nhật hồ sơ':'Đã thêm hồ sơ nhân sự')})}
async function deletePerson(id){if(!confirm('Bạn có chắc muốn xóa hồ sơ này? Thao tác sẽ được ghi vào nhật ký.'))return;try{await api('/personnel/'+id,{method:'DELETE'});toast('Đã xóa hồ sơ');renderPage('personnel')}catch(e){toast(e.message,true)}}
function reportModal(){const opts=state.units.filter(u=>state.user.role!=='unit_lead'||u.id===state.user.unit_id).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('');openModal('Tạo báo cáo mới','Sau khi tạo, bạn có thể gửi báo cáo vào quy trình phê duyệt.',`<div class="form-field"><label>Tiêu đề báo cáo *</label><input id="rTitle" required placeholder="Ví dụ: Báo cáo hoạt động quý IV"></div><div class="form-grid"><div class="form-field"><label>Kỳ báo cáo *</label><input id="rPeriod" required placeholder="Quý IV/2026"></div><div class="form-field"><label>Đơn vị *</label><select id="rUnit" required>${opts}</select></div></div><div class="form-field"><label>Nội dung báo cáo *</label><textarea id="rContent" required placeholder="Tóm tắt hoạt động, kết quả, khó khăn và đề xuất…"></textarea></div>`,async()=>{await api('/reports',{method:'POST',body:JSON.stringify({title:$('#rTitle').value,period:$('#rPeriod').value,unit_id:Number($('#rUnit').value),content:$('#rContent').value})});toast('Đã tạo bản nháp báo cáo')},'Tạo bản nháp')}
function viewReport(id){const r=state.reports.find(x=>x.id===id);if(!r)return;openModal(r.title,'Nội dung và trạng thái xử lý báo cáo',`<div class="form-field"><label>Đơn vị / kỳ báo cáo</label><input disabled value="${esc(r.unit_name+' · '+r.period)}"></div><div class="form-field"><label>Trạng thái</label><div>${statusBadge(r.status)}</div></div><div class="form-field"><label>Nội dung báo cáo</label><textarea disabled>${esc(r.content)}</textarea></div><div class="form-field"><label>Ghi chú người duyệt</label><textarea disabled>${esc(r.review_note||'Chưa có ghi chú')}</textarea></div>`,async()=>{},'Đóng')}
async function submitReport(id){if(!confirm('Gửi báo cáo này để người có thẩm quyền xem xét?'))return;try{await api('/reports/'+id+'/submit',{method:'POST',body:'{}'});toast('Đã gửi báo cáo chờ duyệt');renderPage('reports')}catch(e){toast(e.message,true)}}
function reviewReport(id){openModal('Xem xét báo cáo','Chọn kết quả và ghi chú phản hồi nếu cần.',`<div class="form-field"><label>Kết quả xử lý</label><select id="reviewDecision"><option value="Đã duyệt">Phê duyệt báo cáo</option><option value="Yêu cầu sửa">Yêu cầu chỉnh sửa</option></select></div><div class="form-field"><label>Ghi chú phản hồi</label><textarea id="reviewNote" placeholder="Nhập nhận xét hoặc yêu cầu bổ sung…"></textarea></div>`,async()=>{await api('/reports/'+id+'/review',{method:'POST',body:JSON.stringify({decision:$('#reviewDecision').value,note:$('#reviewNote').value})});toast('Đã cập nhật kết quả xử lý')},'Xác nhận quyết định')}
function paymentModal(id){const d=state.dues.find(x=>x.id===id);if(!d)return;openModal('Tạo yêu cầu thanh toán','Bản demo chỉ ghi nhận yêu cầu; không trừ tiền thật.',`<div class="notice"><span>ⓘ</span><div><strong>${esc(d.unit_name)} · ${esc(d.period)}</strong>Khoản phải thu: ${money(d.amount)}</div></div><div class="form-field"><label>Số tiền (VND)</label><input id="payAmount" type="number" value="${d.amount}" required min="1"></div><div class="form-field"><label>Phương thức dự kiến</label><select id="payMethod"><option>Chuyển khoản ngân hàng</option><option>Ví điện tử</option><option>Tiền mặt (ghi nhận nội bộ)</option></select></div>`,async()=>{const result=await api('/payments',{method:'POST',body:JSON.stringify({dues_id:id,amount:Number($('#payAmount').value),method:$('#payMethod').value})});toast('Tạo yêu cầu thành công: '+result.transaction_ref+' · chưa thu tiền thật')},'Tạo yêu cầu')}
function verifyPayment(id){openModal('Xác minh giao dịch','Chỉ xác nhận sau khi đối chiếu sao kê thực tế của nhà cung cấp.',`<div class="form-field"><label>Kết quả đối soát</label><select id="verifyDecision"><option value="Đã xác minh">Đã nhận tiền / khớp sao kê</option><option value="Không khớp">Không khớp thông tin</option><option value="Thất bại">Giao dịch thất bại</option></select></div><div class="form-field"><label>Mã tham chiếu từ ngân hàng/cổng thanh toán</label><input id="providerRef" placeholder="Nhập mã giao dịch đối tác (nếu có)"></div><div class="form-field"><label>Ghi chú đối soát</label><textarea id="verifyNote" placeholder="Thông tin đối chiếu, ngày nhận tiền…"></textarea></div>`,async()=>{await api('/payments/'+id+'/verify',{method:'POST',body:JSON.stringify({decision:$('#verifyDecision').value,provider_ref:$('#providerRef').value,note:$('#verifyNote').value})});toast('Đã cập nhật trạng thái giao dịch')},'Lưu kết quả')}
async function downloadFile(path){try{const res=await fetch('/api'+path,{headers:{Authorization:'Bearer '+state.token}});if(!res.ok){const d=await res.json();throw Error(d.error||'Không thể xuất file')}const blob=await res.blob();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=path.includes('payments')?'doi-soat-hoi-phi.csv':'bao-cao-hoi.csv';a.click();URL.revokeObjectURL(url);toast('Đã xuất file CSV')}catch(e){toast(e.message,true)}}
async function uploadFile(fileInputId, targetInputId){const file=$('#'+fileInputId).files[0];if(!file)throw new Error('Chưa chọn tệp');if(file.size>10*1024*1024)throw new Error('Tệp tối đa 10MB');const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(r.result);r.onerror=()=>rej(new Error('Không đọc được tệp'));r.readAsDataURL(file)});const out=await api('/upload',{method:'POST',body:JSON.stringify({name:file.name,data})});const target=$('#'+targetInputId);target.value=out.url;toast('Đã tải lên: '+out.name);return out.url}

async function postsHtml(){state.posts=await api('/posts');const canEdit=state.user.role==='admin';return `<div class="notice"><span>📰</span><div><strong>Nội dung website công khai</strong> Chỉ bài ở trạng thái “Đã xuất bản” được hiển thị trên trang chủ. Bài nháp và bài chưa duyệt không xuất hiện công khai.</div></div><div class="toolbar"><div class="search-box">⌕ <input id="tableSearch" placeholder="Tìm theo tiêu đề, tác giả…"></div><select id="postTypeFilter" class="filter-select"><option value="">Tất cả loại</option><option value="news">Tin tức</option><option value="event">Sự kiện</option></select><select id="postStatusFilter" class="filter-select"><option value="">Tất cả trạng thái</option><option>Đã xuất bản</option><option>Bản nháp</option></select>${canEdit?'<button class="btn btn-primary" id="addPost">＋ Viết bài mới</button>':''}</div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>BÀI VIẾT</th><th>LOẠI</th><th>CHUYÊN MỤC</th><th>TRẠNG THÁI</th><th>NỔI BẬT</th><th>THAO TÁC</th></tr></thead><tbody id="dataRows">${state.posts.map(p=>`<tr data-search="${esc((p.title+' '+p.author+' '+(p.category_label||p.category)).toLowerCase())}" data-post-type="${p.type}" data-status="${p.status==='published'?'Đã xuất bản':'Bản nháp'}"><td><div class="person-cell"><span class="mini-avatar">${p.type==='event'?'🗓':'📰'}</span><span><b>${esc(p.title)}</b><small>${esc(p.author||'Ban Biên tập')} · ${dateText(p.published_at||p.created_at)}${p.view_count?` · ${p.view_count} lượt xem`:''}</small></span></div></td><td>${p.type==='event'?'Sự kiện':'Tin tức'}</td><td>${esc(p.category_label||p.category)}</td><td>${statusBadge(p.status==='published'?'Đã xuất bản':'Bản nháp')}</td><td>${p.is_featured?'<span style="color:#e8a13a">★ Đặc sắc</span>':'—'}</td><td><div class="row-actions">${canEdit?`<button class="action-btn" title="Chỉnh sửa" data-edit-post="${p.id}">✎</button><button class="action-btn" title="Xóa" data-delete-post="${p.id}">×</button>`:'—'}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${state.posts.length} bài viết</span><span>Xuất bản trực tiếp lên website công khai</span></div></section>`}

function postModal(p=null){const catOpts=Object.entries(POST_CATS).map(([k,v])=>`<option value="${k}" ${p&&p.category===k?'selected':''}>${esc(v)}</option>`).join('');openModal(p?'Cập nhật bài viết':'Viết bài mới',p?'Chỉnh sửa tin/sự kiện.':'Sau khi xuất bản, bài hiển thị công khai trên website của Hội.',`<div class="form-grid"><div class="form-field full"><label>Tiêu đề *</label><input id="fTitle" required value="${esc(p?.title||'')}" placeholder="Nhập tiêu đề bài viết"></div><div class="form-field"><label>Loại nội dung</label><select id="fType"><option value="news" ${!p||p.type==='news'?'selected':''}>Tin tức</option><option value="event" ${p&&p.type==='event'?'selected':''}>Sự kiện</option></select></div><div class="form-field"><label>Chuyên mục</label><select id="fCat">${catOpts}</select></div><div class="form-field"><label>Tác giả</label><input id="fAuthor" value="${esc(p?.author||'')}" placeholder="Tên người viết / ban biên tập"></div><div class="form-field"><label>Trạng thái</label><select id="fStatus"><option value="draft" ${!p||p.status==='draft'?'selected':''}>Bản nháp</option><option value="published" ${p&&p.status==='published'?'selected':''}>Đã xuất bản</option></select></div><div class="form-field"><label>Nổi bật</label><select id="fFeatured"><option value="0" ${!p||!p.is_featured?'selected':''}>Không</option><option value="1" ${p&&p.is_featured?'selected':''}>Đặc sắc (ưu tiên hiển thị)</option></select></div><div class="form-field event-only" id="fEventDateBox" style="display:none"><label>Ngày sự kiện</label><input id="fEventDate" type="date" value="${esc(p?.event_date||'')}"></div><div class="form-field event-only" style="display:none"><label>Địa điểm</label><input id="fLocation" value="${esc(p?.event_location||'')}"></div><div class="form-field full"><label>Mô tả ngắn</label><textarea id="fExcerpt">${esc(p?.excerpt||'')}</textarea></div><div class="form-field full"><label>Ảnh đại diện (đường dẫn hoặc tải lên)</label><div style="display:flex;gap:8px;flex-wrap:wrap"><input id="fCover" value="${esc(p?.cover_image||'')}" placeholder="https://… hoặc /uploads/…" style="flex:1"><label class="btn btn-soft small" style="flex-shrink:0;margin:0"><input type="file" id="fCoverFile" accept="image/*" hidden> Tải ảnh ↑</label></div></div><div class="form-field full"><label>Nội dung chi tiết (HTML)</label><textarea id="fContent" style="min-height:180px">${esc(p?.content||'')}</textarea></div><div class="form-field full"><label>Tài liệu đính kèm (sự kiện / bài viết)</label><div style="display:flex;gap:8px;flex-wrap:wrap"><input id="fAttach" value="${esc(p?.attachment||'')}" placeholder="/uploads/… hoặc link tải" style="flex:1"><label class="btn btn-soft small" style="flex-shrink:0;margin:0"><input type="file" id="fAttachFile" accept=".pdf,.doc,.docx,.xlsx,.pdf,.png,.jpg,.jpeg" hidden> Tải tệp ↑</label></div></div></div>`,async()=>{await uploadOptional('fCoverFile',p?.cover_image).then(u=>{if(u)$('#fCover').value=u});await uploadOptional('fAttachFile',p?.attachment).then(u=>{if(u)$('#fAttach').value=u});const isEvent=$('#fType').value==='event';const data={title:$('#fTitle').value,type:$('#fType').value,category:$('#fCat').value,author:$('#fAuthor').value,status:$('#fStatus').value,is_featured:$('#fFeatured').value==='1',excerpt:$('#fExcerpt').value,cover_image:$('#fCover').value,attachment:$('#fAttach').value,content:$('#fContent').value,event_date:isEvent?($('#fEventDate').value||null):null,event_location:isEvent?$('#fLocation').value:''};await api(p?'/posts/'+p.id:'/posts',{method:p?'PUT':'POST',body:JSON.stringify(data)});toast(p?'Đã cập nhật bài viết':'Đã tạo bài viết')},'Lưu bài viết');$('#fType').addEventListener('change',()=>{$$('.event-only').forEach(el=>el.style.display=$('#fType').value==='event'?'':'none')});if(p&&p.type==='event')$$('.event-only').forEach(el=>el.style.display='')}
async function uploadOptional(fileInputId,existing){const input=$('#'+fileInputId);if(!input||!input.files.length)return existing||'';return uploadFile(fileInputId,fileInputId.replace('File',''));}

async function documentsHtml(){state.documents=await api('/documents');const canEdit=state.user.role==='admin';return `<div class="notice"><span>📚</span><div><strong>Thư viện văn bản công khai</strong> Văn bản có tệp đính kèm cho phép khách truy cập tải xuống. Trạng thái “Đã xuất bản” mới hiển thị.</div></div><div class="toolbar"><div class="search-box">⌕ <input id="tableSearch" placeholder="Tìm theo số, tiêu đề, cơ quan…"></div><select id="docTypeFilter" class="filter-select"><option value="">Tất cả loại</option>${DOC_TYPES.map(t=>`<option value="${t}">${esc(t)}</option>`).join('')}</select><select id="postStatusFilter" class="filter-select"><option value="">Tất cả trạng thái</option><option>Đã xuất bản</option><option>Bản nháp</option></select>${canEdit?'<button class="btn btn-primary" id="addDoc">＋ Thêm văn bản</button>':''}</div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>VĂN BẢN</th><th>SỐ / LOẠI</th><th>LĨNH VỰC</th><th>NGÀY BAN HÀNH</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody id="dataRows">${state.documents.map(d=>`<tr data-search="${esc((d.doc_number+' '+d.title+' '+d.issuer).toLowerCase())}" data-doc-type="${esc(d.doc_type)}" data-status="${d.status==='published'?'Đã xuất bản':'Bản nháp'}"><td><div class="person-cell"><span class="mini-avatar">▤</span><span><b>${esc(d.title)}</b><small>${esc(d.issuer||'—')}${d.download_count?` · ${d.download_count} lượt tải`:''}</small></span></div></td><td>${esc(d.doc_number||'—')}<small style="display:block;color:#8b99ac">${esc(d.doc_type)}</small></td><td>${esc(d.category_label||d.category)}</td><td>${d.issued_at?dateText(d.issued_at):'—'}</td><td>${statusBadge(d.status==='published'?'Đã xuất bản':'Bản nháp')}</td><td><div class="row-actions">${canEdit?`<button class="action-btn" title="Chỉnh sửa" data-edit-doc="${d.id}">✎</button><button class="action-btn" title="Xóa" data-delete-doc="${d.id}">×</button>`:'—'}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${state.documents.length} văn bản</span><span>Công khai trên thư viện website</span></div></section>`}

function docModal(d=null){const catOpts=Object.entries(DOC_CATS).map(([k,v])=>`<option value="${k}" ${d&&d.category===k?'selected':''}>${esc(v)}</option>`).join('');const typeOpts=DOC_TYPES.map(t=>`<option ${d&&d.doc_type===t?'selected':''}>${esc(t)}</option>`).join('');openModal(d?'Cập nhật văn bản':'Thêm văn bản','Văn bản dạng bản nháp không công khai cho tới khi chuyển sang “Đã xuất bản”.',`<div class="form-grid"><div class="form-field full"><label>Tiêu đề văn bản *</label><input id="dTitle" required value="${esc(d?.title||'')}" placeholder="Tên văn bản"></div><div class="form-field"><label>Số ký hiệu</label><input id="dNumber" value="${esc(d?.doc_number||'')}" placeholder="Ví dụ: 05/QC-TC"></div><div class="form-field"><label>Loại văn bản</label><select id="dType">${typeOpts}</select></div><div class="form-field"><label>Lĩnh vực</label><select id="dCat">${catOpts}</select></div><div class="form-field"><label>Cơ quan ban hành</label><input id="dIssuer" value="${esc(d?.issuer||'')}" placeholder="Ví dụ: Ban Thường vụ Trung ương Hội"></div><div class="form-field"><label>Ngày ban hành</label><input id="dDate" type="date" value="${esc(d?.issued_at||'')}"></div><div class="form-field"><label>Trạng thái</label><select id="dStatus"><option value="draft" ${!d||d.status==='draft'?'selected':''}>Bản nháp</option><option value="published" ${d&&d.status==='published'?'selected':''}>Đã xuất bản</option></select></div><div class="form-field full"><label>Tóm tắt nội dung</label><textarea id="dSummary">${esc(d?.summary||'')}</textarea></div><div class="form-field full"><label>Tệp đính kèm (PDF)</label><div style="display:flex;gap:8px;flex-wrap:wrap"><input id="dFile" value="${esc(d?.file_url||'')}" placeholder="/uploads/… hoặc link tải" style="flex:1"><label class="btn btn-soft small" style="flex-shrink:0;margin:0"><input type="file" id="dFileUp" accept=".pdf,.doc,.docx,.xlsx" hidden> Tải tệp ↑</label></div><span class="muted" style="font-size:11px">Chấp nhận PDF, DOC/DOCX, XLS/XLSX tối đa 10MB.</span></div></div>`,async()=>{await uploadOptional('dFileUp',d?.file_url).then(u=>{if(u)$('#dFile').value=u});const data={title:$('#dTitle').value,doc_number:$('#dNumber').value,doc_type:$('#dType').value,category:$('#dCat').value,issuer:$('#dIssuer').value,issued_at:$('#dDate').value||null,summary:$('#dSummary').value,file_url:$('#dFile').value,status:$('#dStatus').value};await api(d?'/documents/'+d.id:'/documents',{method:d?'PUT':'POST',body:JSON.stringify(data)});toast(d?'Đã cập nhật văn bản':'Đã thêm văn bản')},'Lưu văn bản')}

async function deleteContent(endpoint,id,label){if(!confirm(`Xóa ${label} này? Thao tác sẽ được ghi vào nhật ký hệ thống.`))return;try{await api(endpoint+'/'+id,{method:'DELETE'});toast(`Đã xóa ${label}`);renderPage(state.page)}catch(e){toast(e.message,true)}}

async function usersHtml(){state.users=await api('/users');return `<div class="notice"><span>♟</span><div><strong>Quản lý tài khoản</strong> Tạo tài khoản, gán vai trò và đơn vị, khóa/mở khóa khi cần. Mỗi đơn vị chỉ truy cập dữ liệu trong phạm vi của mình.</div></div><div class="toolbar"><div class="search-box">⌕ <input id="tableSearch" placeholder="Tìm tên đăng nhập, họ tên…"></div><select id="userRoleFilter" class="filter-select"><option value="">Tất cả vai trò</option><option value="admin">Quản trị viên</option><option value="reviewer">Người duyệt báo cáo</option><option value="unit_lead">Trưởng đơn vị</option><option value="finance">Phụ trách tài chính</option><option value="viewer">Chỉ xem</option></select><button class="btn btn-primary" id="addUser">＋ Tạo tài khoản</button></div><section class="card table-card"><div class="table-scroll"><table><thead><tr><th>TÀI KHOẢN</th><th>VAI TRÒ</th><th>ĐƠN VỊ</th><th>TRẠNG THÁI</th><th>THAO TÁC</th></tr></thead><tbody id="dataRows">${state.users.map(u=>`<tr data-search="${esc((u.username+' '+u.full_name).toLowerCase())}" data-role="${u.role}"><td><div class="person-cell"><span class="mini-avatar">${initials(u.full_name)}</span><span><b>${esc(u.username)}</b><small>${esc(u.full_name)}</small></span></div></td><td>${esc(roleNames[u.role]||u.role)}</td><td>${esc(u.unit_name||'—')}</td><td>${statusBadge(u.active?'Đang hoạt động':'Bị khóa')}</td><td><div class="row-actions">${u.username==='admin'?'<span class="muted">—</span>':`<button class="action-btn" title="Chỉnh sửa" data-edit-user="${u.id}">✎</button><button class="action-btn" title="${u.active?'Khóa':'Mở khóa'}" data-toggle-user="${u.id}">${u.active?'🔒':'🔓'}</button><button class="action-btn" title="Đặt lại mật khẩu" data-reset-pass="${u.id}">✦</button>`}</div></td></tr>`).join('')}</tbody></table></div><div class="table-footer"><span>${state.users.length} tài khoản</span><span>Tài khoản admin không thể tự khóa</span></div></section>`}

function userModal(u=null){const unitOpts=state.units.map(x=>`<option value="${x.id}" ${u&&u.unit_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('');const roleOpts=Object.entries({admin:'Quản trị viên',reviewer:'Người duyệt báo cáo',unit_lead:'Trưởng đơn vị',finance:'Phụ trách tài chính',viewer:'Chỉ xem'}).map(([k,v])=>`<option value="${k}" ${u&&u.role===k?'selected':''}>${esc(v)}</option>`).join('');openModal(u?'Cập nhật tài khoản':'Tạo tài khoản mới',u?'Điều chỉnh vai trò, đơn vị và trạng thái tài khoản.':'Tài khoản được gán cho một đơn vị với vai trò xác định.',`<div class="form-grid"><div class="form-field"><label>Tên đăng nhập</label><input id="uname" value="${esc(u?.username||'')}" ${u?'disabled':''} placeholder="vd: hoianh"></div><div class="form-field"><label>Họ và tên</label><input id="ufull" required value="${esc(u?.full_name||'')}"></div><div class="form-field"><label>Vai trò</label><select id="urole">${roleOpts}</select></div><div class="form-field"><label>Đơn vị</label><select id="uunit">${unitOpts}</select></div>${!u?`<div class="form-field full"><label>Mật khẩu ban đầu (tối thiểu 10 ký tự)</label><input id="upass" type="password" required minlength="10"></div>`:''}<div class="form-field full" ${u?'':'hidden'}><label>Trạng thái</label><select id="uactive"><option value="1" ${u&&u.active?'selected':''}>Đang hoạt động</option><option value="0" ${u&&!u.active?'selected':''}>Bị khóa</option></select></div></div>`,async()=>{const data={full_name:$('#ufull').value,role:$('#urole').value,unit_id:Number($('#uunit').value)};if(u){data.active=$('#uactive').value==='1';await api('/users/'+u.id,{method:'PUT',body:JSON.stringify(data)})}else{data.username=$('#uname').value;data.password=$('#upass').value;await api('/users',{method:'POST',body:JSON.stringify(data)})}toast(u?'Đã cập nhật tài khoản':'Đã tạo tài khoản')},u?'Lưu thay đổi':'Tạo tài khoản')}
async function toggleUser(id){const u=state.users.find(x=>x.id===id);if(!u)return;if(!confirm(`${u.active?'Khóa':'Mở khóa'} tài khoản “${u.username}”?`))return;try{await api('/users/'+id,{method:'PUT',body:JSON.stringify({active:!u.active})});toast('Đã cập nhật trạng thái');renderPage('users')}catch(e){toast(e.message,true)}}
function resetPassword(id){const u=state.users.find(x=>x.id===id);if(!u)return;openModal(`Đặt lại mật khẩu — ${u.username}`,'Người dùng phải đổi mật khẩu lần đầu sau khi được cấp lại.',`<div class="form-field"><label>Mật khẩu mới (tối thiểu 10 ký tự)</label><input id="rpPass" type="password" required minlength="10"></div>`,async()=>{await api('/users/'+id+'/reset-password',{method:'POST',body:JSON.stringify({password:$('#rpPass').value})});toast('Đã đặt lại mật khẩu')},'Đặt lại mật khẩu')}

async function settingsHtml(){state.settings=await api('/settings');const s=state.settings;const f=(k,label,placeholder='')=>`<div class="form-field full"><label>${label}</label><input id="st_${k}" value="${esc(s[k]||'')}" placeholder="${esc(placeholder)}"></div>`;return `<div class="notice"><span>⚙</span><div><strong>Cấu hình hiển thị công khai</strong> Thông tin này xuất hiện trên trang chủ và chân trang website công khai.</div></div><section class="card" style="max-width:860px"><div class="form-grid">${f('site_name','Tên Hội (đầy đủ)')}${f('site_short','Tên viết tắt hiển thị trên logo')}${f('site_tagline','Khẩu hiệu (tagline)')}${f('hero_title','Tiêu đề banner trang chủ')}<div class="form-field full"><label>Mô tả banner trang chủ</label><textarea id="st_hero_text">${esc(s.hero_text||'')}</textarea></div>${f('about_title','Tiêu đề mục giới thiệu')}<div class="form-field full"><label>Nội dung giới thiệu Hội</label><textarea id="st_about_text">${esc(s.about_text||'')}</textarea></div>${f('address','Địa chỉ trụ sở')}${f('email','Email liên hệ')}${f('phone','Số điện thoại')}${f('hours','Giờ làm việc')}${f('facebook','Link Facebook (nếu có)')}${f('youtube','Link YouTube (nếu có)')}</div><div class="flex gap-12" style="justify-content:flex-end;margin-top:8px"><button class="btn btn-outline" onclick="renderPage('settings')">Hủy</button><button class="btn btn-primary" id="saveSettings">Lưu cấu hình</button></div></section>`}
async function saveSettings(){const keys=['site_name','site_short','site_tagline','hero_title','hero_text','about_title','about_text','address','email','phone','hours','facebook','youtube'];const data={};keys.forEach(k=>{const el=$('#st_'+k);if(el)data[k]=el.value});try{state.settings=await api('/settings',{method:'PUT',body:JSON.stringify(data)});toast('Đã lưu cấu hình website');await renderPage('settings')}catch(e){toast(e.message,true)}}

(async()=>{if(state.token){try{const d=await api('/auth/me');setLoggedIn(d.user)}catch{logout(false)}}})();
